CREATE TABLE public.st_teams (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,department text NOT NULL,name text NOT NULL,mission text DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,user_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.st_teams TO authenticated; GRANT ALL ON public.st_teams TO service_role;
ALTER TABLE public.st_teams ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_teams ON public.st_teams FOR ALL TO authenticated USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id);
CREATE TABLE public.st_agents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,team_id uuid REFERENCES public.st_teams(id) ON DELETE SET NULL,department text NOT NULL,name text NOT NULL,role text NOT NULL DEFAULT '',is_chief boolean NOT NULL DEFAULT false,model text NOT NULL DEFAULT 'openai/gpt-5.6-terra',system_prompt text NOT NULL DEFAULT '',temperature numeric NOT NULL DEFAULT 0.6,skills text NOT NULL DEFAULT '',tone text NOT NULL DEFAULT '',color text NOT NULL DEFAULT 'autre',pos_x numeric NOT NULL DEFAULT 0,pos_y numeric NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'idle',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.st_agents TO authenticated; GRANT ALL ON public.st_agents TO service_role;
ALTER TABLE public.st_agents ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_agents ON public.st_agents FOR ALL TO authenticated USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id AND (team_id IS NULL OR EXISTS(SELECT 1 FROM public.st_teams t WHERE t.id=team_id AND t.user_id=auth.uid())));
CREATE TABLE public.st_missions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,team_id uuid NOT NULL REFERENCES public.st_teams(id) ON DELETE CASCADE,objective text NOT NULL,status text NOT NULL DEFAULT 'planning',summary text DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.st_missions TO authenticated; GRANT ALL ON public.st_missions TO service_role;
ALTER TABLE public.st_missions ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_missions ON public.st_missions FOR ALL TO authenticated USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id AND EXISTS(SELECT 1 FROM public.st_teams t WHERE t.id=team_id AND t.user_id=auth.uid()));
CREATE TABLE public.st_tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,team_id uuid NOT NULL REFERENCES public.st_teams(id) ON DELETE CASCADE,mission_id uuid REFERENCES public.st_missions(id) ON DELETE CASCADE,agent_id uuid REFERENCES public.st_agents(id) ON DELETE SET NULL,title text NOT NULL,brief text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'todo',result text DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.st_tasks TO authenticated; GRANT ALL ON public.st_tasks TO service_role;
ALTER TABLE public.st_tasks ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_tasks ON public.st_tasks FOR ALL TO authenticated USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id AND EXISTS(SELECT 1 FROM public.st_teams t WHERE t.id=team_id AND t.user_id=auth.uid()) AND (mission_id IS NULL OR EXISTS(SELECT 1 FROM public.st_missions m WHERE m.id=mission_id AND m.user_id=auth.uid() AND m.team_id=st_tasks.team_id)) AND (agent_id IS NULL OR EXISTS(SELECT 1 FROM public.st_agents a WHERE a.id=agent_id AND a.user_id=auth.uid() AND a.team_id=st_tasks.team_id)));
CREATE FUNCTION public.st_touch_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END; $$;
CREATE TRIGGER st_tasks_touch BEFORE UPDATE ON public.st_tasks FOR EACH ROW EXECUTE FUNCTION public.st_touch_updated_at();
CREATE INDEX ON public.st_agents(user_id); CREATE INDEX ON public.st_tasks(user_id,team_id); CREATE INDEX ON public.st_missions(user_id,team_id);
CREATE TABLE public.st_department_modules(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,department text NOT NULL,modules text[] NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,department));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.st_department_modules TO authenticated; GRANT ALL ON public.st_department_modules TO service_role;
ALTER TABLE public.st_department_modules ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_modules ON public.st_department_modules FOR ALL TO authenticated USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id);
CREATE TABLE public.st_custom_departments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,key text NOT NULL,label text NOT NULL,blurb text NOT NULL DEFAULT '',default_team text NOT NULL DEFAULT 'Nouvelle équipe',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,key));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.st_custom_departments TO authenticated; GRANT ALL ON public.st_custom_departments TO service_role;
ALTER TABLE public.st_custom_departments ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_departments ON public.st_custom_departments FOR ALL TO authenticated USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id);
ALTER PUBLICATION supabase_realtime ADD TABLE public.st_agents,public.st_teams,public.st_tasks,public.st_missions;